from __future__ import annotations

from pathlib import Path

import httpx

from apps.collectors.treasury.rates import (
    TREASURY_RATE_SYMBOLS,
    collect_treasury_rate_curves,
    treasury_nominal_csv_url,
    treasury_real_csv_url,
    treasury_textview_url,
)

# Independently verified official coordinates, not generated by the helper
# under test. A fixture keyed by that helper would hide a broken source URL.
NOMINAL_TEXTVIEW_URL = (
    "https://home.treasury.gov/resource-center/data-chart-center/interest-rates/TextView"
    "?type=daily_treasury_yield_curve&field_tdr_date_value=2026"
)
REAL_TEXTVIEW_URL = (
    "https://home.treasury.gov/resource-center/data-chart-center/interest-rates/TextView"
    "?type=daily_treasury_real_yield_curve&field_tdr_date_value=2026"
)


def test_textview_urls_match_independently_verified_official_coordinates() -> None:
    assert treasury_textview_url(2026, "nominal") == NOMINAL_TEXTVIEW_URL
    assert treasury_textview_url(2026, "real") == REAL_TEXTVIEW_URL


NOMINAL_CSV = """Date,"1 Mo","3 Mo","2 Yr","5 Yr","10 Yr","30 Yr"
09/07/2026,4.00,4.20,4.50,4.70,4.90,5.30
09/04/2026,4.00,4.10,4.37,4.55,4.78,5.24
09/03/2026,4.00,4.05,4.34,4.52,4.77,5.25
"""
REAL_CSV = """Date,"5 YR","10 YR","30 YR"
09/07/2026,1.90,2.50,2.10
09/04/2026,2.00,2.43,2.20
09/03/2026,1.99,2.42,2.19
"""


class FixtureClient:
    def __init__(self, nominal: str = NOMINAL_CSV, real: str = REAL_CSV, *, real_status: int = 200) -> None:
        self.nominal = nominal
        self.real = real
        self.real_status = real_status
        self.urls: list[str] = []

    def get(self, url: str) -> httpx.Response:
        self.urls.append(url)
        is_real = "daily_treasury_real_yield_curve" in url
        body = self.real if is_real else self.nominal
        status = self.real_status if is_real else 200
        return httpx.Response(status, content=body.encode("utf-8"), request=httpx.Request("GET", url))


def test_treasury_collector_emits_latest_common_cutoff_date_and_archives_raw_csv(tmp_path: Path) -> None:
    client = FixtureClient()

    result = collect_treasury_rate_curves(
        retrieved_date="2026-09-06",
        storage_root=tmp_path,
        client=client,
    )

    assert result.unavailable_symbols == []
    assert [point.symbol for point in result.points] == list(TREASURY_RATE_SYMBOLS)
    assert {point.date for point in result.points} == {"2026-09-04"}
    assert {point.symbol: point.value for point in result.points} == {
        "DGS3MO": 4.10,
        "DGS2": 4.37,
        "DGS5": 4.55,
        "DGS10": 4.78,
        "DGS30": 5.24,
        "DFII5": 2.00,
        "DFII10": 2.43,
        "DFII30": 2.20,
    }
    assert len(client.urls) == 2
    assert client.urls == [treasury_nominal_csv_url(2026), treasury_real_csv_url(2026)]
    assert len({point.raw_path for point in result.points}) == 2
    assert all((tmp_path / point.raw_path).is_file() for point in result.points)
    refs = {ref["symbol"]: ref for ref in result.source_refs}
    assert refs["DGS10"]["curve"] == "nominal"
    assert refs["DFII10"]["curve"] == "real"
    assert all(ref["observation_cutoff_date"] == "2026-09-06" for ref in refs.values())
    assert all(ref["observation_date"] == "2026-09-04" for ref in refs.values())
    assert all(ref["status"] == "available" for ref in refs.values())


