def test_treasury_collector_fails_closed_without_a_common_observation(tmp_path: Path) -> None:
    nominal = """Date,"3 Mo","2 Yr","5 Yr","10 Yr","30 Yr"
09/04/2026,4.10,4.37,4.55,4.78,5.24
"""
    real = """Date,"5 YR","10 YR","30 YR"
09/03/2026,1.99,2.42,2.19
"""

    result = collect_treasury_rate_curves(
        retrieved_date="2026-09-04",
        storage_root=tmp_path,
        client=FixtureClient(nominal=nominal, real=real),
    )

    assert result.points == []
    assert result.unavailable_symbols == list(TREASURY_RATE_SYMBOLS)
    assert all("No common complete Treasury curve observation" in ref["reason"] for ref in result.source_refs)
    assert len(list((tmp_path / "raw/macro/treasury_rates/2026-09-04").glob("*.csv"))) == 2


def test_treasury_collector_keeps_successful_archive_when_other_curve_request_fails(tmp_path: Path) -> None:
    result = collect_treasury_rate_curves(
        retrieved_date="2026-09-06",
        storage_root=tmp_path,
        client=FixtureClient(real_status=503),
    )

    assert result.points == []
    assert result.unavailable_symbols == list(TREASURY_RATE_SYMBOLS)
    nominal_refs = [ref for ref in result.source_refs if ref["curve"] == "nominal"]
    real_refs = [ref for ref in result.source_refs if ref["curve"] == "real"]
    assert nominal_refs and all("raw_path" in ref for ref in nominal_refs)
    assert real_refs and all("raw_path" not in ref for ref in real_refs)
    assert all((tmp_path / ref["raw_path"]).is_file() for ref in nominal_refs)


# TextView fixtures preserve the official table structure, including empty
# cells and nested header markup; values are synthetic and no network is used.
NOMINAL_HTML = '''<html><table><thead><tr><th>Date</th><th>3 Mo</th>
<th><span>2 Yr</span></th><th>5 Yr</th><th>10 Yr</th><th>30 Yr</th></tr></thead>
<tbody><tr><td>09/04/2026</td><td>4.10</td><td>4.37</td><td>4.55</td><td>4.78</td><td>5.24</td></tr>
<tr><td>09/03/2026</td><td>4.05</td><td>4.34</td><td>4.52</td><td>4.77</td><td>5.25</td></tr></tbody></table></html>'''


class RouteClient:
    def __init__(self, responses):
        self.responses = responses
        self.urls = []

    def get(self, url):
        self.urls.append(url)
        status, body = self.responses.get(url, (503, 'inaccessible'))
        return httpx.Response(status, content=body.encode(), request=httpx.Request('GET', url))


def test_nominal_html_fallback_is_once_archived_and_does_not_retry_successful_real(tmp_path):
    client = RouteClient({
        treasury_nominal_csv_url(2026): (503, 'blocked'),
        NOMINAL_TEXTVIEW_URL: (200, NOMINAL_HTML),
        treasury_real_csv_url(2026): (200, REAL_CSV),
    })
    result = collect_treasury_rate_curves(retrieved_date='2026-09-06', storage_root=tmp_path, client=client)
    assert len(client.urls) == 3
    assert len(result.points) == 8
    assert {p.date for p in result.points} == {'2026-09-04'}
    nominal = next(p for p in result.points if p.symbol == 'DGS10')
    assert nominal.value == 4.78
    assert nominal.source_url == NOMINAL_TEXTVIEW_URL
    assert nominal.raw_path.endswith('.html')
    assert (tmp_path / nominal.raw_path).read_text() == NOMINAL_HTML
    ref = next(r for r in result.source_refs if r.get('symbol') == 'DGS10')
    assert ref['source_format'] == 'html' and '503' in ref['fallback_reason']
    assert next(p for p in result.points if p.symbol == 'DFII10').raw_path.endswith('.csv')


def test_history_emits_complete_common_dates_and_verifiable_day_week_month_anchors(tmp_path):
    from apps.features.macro.snapshot import build_macro_snapshot

    nominal = 'Date,3 Mo,2 Yr,5 Yr,10 Yr,30 Yr\n'
    real = 'Date,5 YR,10 YR,30 YR\n'
    for day, value in [('2026-08-01', 4.0), ('2026-08-02', 4.1), ('2026-09-02', 4.2),
                       ('2026-09-25', 4.3), ('2026-10-01', 4.4), ('2026-10-02', 4.5),
                       ('2026-10-05', 99.0)]:
        nominal += f'{day},4,4,4,{value},5\n'
        real += f'{day},2,2,3\n'
    client = FixtureClient(nominal, real)
    result = collect_treasury_rate_curves(retrieved_date='2026-10-03', storage_root=tmp_path,
                                          client=client, include_history=True)
    assert {p.date for p in result.points} == {
        '2026-08-02', '2026-09-02', '2026-09-25', '2026-10-01', '2026-10-02'}
    assert len(result.points) == 40
    assert len(client.urls) == 2
    assert all((tmp_path / ref['raw_path']).is_file() for ref in result.source_refs)
    assert {(r['symbol'], r['observation_date'], r['raw_path']) for r in result.source_refs} == {
        (p.symbol, p.date, p.raw_path) for p in result.points}
    macro = build_macro_snapshot([p.to_dict() for p in result.points], as_of='2026-10-03')
    rate = macro.indicators['US10Y']
    assert rate.date == '2026-10-02' and rate.value == 4.5
    assert rate.previous_date == '2026-10-01' and rate.daily_change == .1
    assert rate.weekly_anchor_date == '2026-09-25' and rate.weekly_change == .2
    assert rate.monthly_change == .3
    assert macro.source_refs['DGS10']['raw_path'] == next(p.raw_path for p in result.points if p.symbol == 'DGS10')


def test_history_cross_year_window_fetches_only_two_years_and_joins_common_dates(tmp_path):
    client = RouteClient({
        treasury_nominal_csv_url(2025): (200, 'Date,10 Yr\n11/01/2025,4\n11/02/2025,4.1\n12/26/2025,4.2\n12/31/2025,4.3\n'),
        treasury_real_csv_url(2025): (200, 'Date,10 YR\n11/02/2025,2\n12/26/2025,2\n12/30/2025,2\n'),
        treasury_nominal_csv_url(2026): (200, 'Date,10 Yr\n01/02/2026,4.4\n01/05/2026,99\n'),
        treasury_real_csv_url(2026): (200, 'Date,10 YR\n01/02/2026,2.1\n01/05/2026,99\n'),
    })
    result = collect_treasury_rate_curves(retrieved_date='2026-01-03', storage_root=tmp_path,
                                          client=client, symbols=('DGS10', 'DFII10'), include_history=True)
    assert len(client.urls) == 4
    assert {p.date for p in result.points} == {'2025-11-02', '2025-12-26', '2026-01-02'}
    assert len({p.raw_path for p in result.points}) == 4
    assert all(p.date[:4] in p.raw_path for p in result.points)


def test_both_endpoints_inaccessible_is_bounded_and_explicit(tmp_path):
    client = RouteClient({})
    result = collect_treasury_rate_curves(retrieved_date='2026-10-03', storage_root=tmp_path, client=client)
    assert len(client.urls) == 4 and len(set(client.urls)) == 4
    assert not result.points and result.unavailable_symbols == list(TREASURY_RATE_SYMBOLS)
    assert all(r['status'] == 'unavailable' and r['reason'] for r in result.source_refs)
    assert not list(tmp_path.rglob('*.*'))


def test_malformed_csv_is_archived_before_html_fallback(tmp_path):
    from apps.collectors.treasury.rates import treasury_textview_url

    client = RouteClient({treasury_nominal_csv_url(2026): (200, '<html>blocked</html>'),
                          treasury_textview_url(2026, 'nominal'): (200, NOMINAL_HTML),
                          treasury_real_csv_url(2026): (200, REAL_CSV)})
    result = collect_treasury_rate_curves(retrieved_date='2026-09-06', storage_root=tmp_path, client=client)
    assert len(result.points) == 8
    failed = next(r for r in result.source_refs if r['status'] == 'unavailable')
    assert (tmp_path / failed['raw_path']).read_text() == '<html>blocked</html>'
    assert failed['source_format'] == 'csv'


def test_malformed_html_missing_and_non_numeric_cells_fail_closed(tmp_path):
    from apps.collectors.treasury.rates import treasury_textview_url

    for index, html in enumerate([
        NOMINAL_HTML.replace('<td>4.78</td>', ''),
        NOMINAL_HTML.replace('<td>4.78</td>', '<td>').replace('<td>4.77</td>', '<td>'),
        NOMINAL_HTML.replace('4.78', 'NaN').replace('4.77', 'N/A'),
        NOMINAL_HTML.replace('09/04/2026', 'bad-date'),
        NOMINAL_HTML.replace('10 Yr', 'missing-header'),
    ]):
        client = RouteClient({treasury_textview_url(2026, 'nominal'): (200, html),
                              treasury_real_csv_url(2026): (200, REAL_CSV)})
        root = tmp_path / str(index)
        result = collect_treasury_rate_curves(retrieved_date='2026-09-06', storage_root=root, client=client)
        assert not result.points
        assert len(client.urls) == 3
        assert any(r['source_format'] == 'html' and r['status'] == 'unavailable'
                   and (root / r['raw_path']).read_text() == html
                   for r in result.source_refs if 'raw_path' in r)


def test_internal_client_uses_configured_environment_and_is_closed(monkeypatch, tmp_path):
    class InternalClient(FixtureClient):
        def __init__(self, **kwargs):
            super().__init__()
            assert kwargs['trust_env'] is True
            assert 'proxy' not in kwargs
            self.closed = False

        def __enter__(self):
            return self

        def __exit__(self, *args):
            self.closed = True

    clients = []

    def factory(**kwargs):
        client = InternalClient(**kwargs)
        clients.append(client)
        return client

    monkeypatch.setattr(httpx, 'Client', factory)
    result = collect_treasury_rate_curves(retrieved_date='2026-09-06', storage_root=tmp_path)
    assert len(result.points) == 8 and clients[0].closed


def test_real_html_fallback_retains_zero_and_rejects_future_rows(tmp_path):
    html = '<table><tr><th>Date</th><th>5 YR</th><th>10 YR</th><th>30 YR</th></tr>'
    html += '<tr><td>09/04/2026</td><td>0</td><td>2.43</td><td>2.2</td></tr>'
    html += '<tr><td>09/07/2026</td><td>99</td><td>99</td><td>99</td></tr></table>'
    client = RouteClient({treasury_nominal_csv_url(2026): (200, NOMINAL_CSV),
                          REAL_TEXTVIEW_URL: (200, html)})
    result = collect_treasury_rate_curves(retrieved_date='2026-09-06', storage_root=tmp_path,
                                          client=client, include_history=True)
    assert {p.date for p in result.points} == {'2026-09-04'}
    zero = next(p for p in result.points if p.symbol == 'DFII5')
    assert zero.value == 0 and zero.raw_path.endswith('.html')
    assert zero.source_url == REAL_TEXTVIEW_URL
    assert all(r['source'] != zero.source for r in result.source_refs if r['status'] == 'unavailable')


def test_partial_prior_year_failure_keeps_latest_and_records_history_gap(tmp_path):
    client = RouteClient({treasury_nominal_csv_url(2026): (200, 'Date,10 Yr\n01/02/2026,4.4\n'),
                          treasury_real_csv_url(2026): (200, 'Date,10 YR\n01/02/2026,2.1\n')})
    result = collect_treasury_rate_curves(retrieved_date='2026-01-03', storage_root=tmp_path,
                                          client=client, symbols=('DGS10', 'DFII10'), include_history=True)
    assert len(client.urls) == 6
    assert len(result.points) == 2 and result.unavailable_symbols == []
    assert {p.date for p in result.points} == {'2026-01-02'}
    failures = [r for r in result.source_refs if r['status'] == 'unavailable']
    assert len(failures) == 4 and all('2025' in r['source_url'] and r['reason'] for r in failures)


def test_real_textview_inactive_duplicate_tenors_do_not_hide_active_curve(tmp_path):
    # Official TextView's real-curve header includes inactive nominal columns
    # with repeated 30 Yr and COUPON EQUIVALENT names. Values are fixtures.
    html = ('<table><tr><th>Date</th><th>5 YR</th><th>7 YR</th><th>10 YR</th>'
            '<th>20 YR</th><th>30 YR</th><th>COUPON EQUIVALENT</th>'
            '<th>COUPON EQUIVALENT</th><th>20 Yr</th><th>30 Yr</th></tr>'
            '<tr><td>09/04/2026</td><td>2.1</td><td>2.2</td><td>2.43</td>'
            '<td>2.5</td><td>2.6</td><td>N/A</td><td>N/A</td><td>N/A</td><td>N/A</td></tr></table>')
    client = RouteClient({treasury_nominal_csv_url(2026): (200, NOMINAL_CSV),
                          REAL_TEXTVIEW_URL: (200, html)})
    result = collect_treasury_rate_curves(retrieved_date='2026-09-06', storage_root=tmp_path, client=client)
    assert len(result.points) == 8
    assert next(p.value for p in result.points if p.symbol == 'DFII30') == 2.6
    ambiguous = html.replace('<td>N/A</td></tr>', '<td>9.9</td></tr>')
    client = RouteClient({treasury_nominal_csv_url(2026): (200, NOMINAL_CSV),
                          REAL_TEXTVIEW_URL: (200, ambiguous)})
    result = collect_treasury_rate_curves(retrieved_date='2026-09-06', storage_root=tmp_path, client=client)
    assert not result.points
    assert any('ambiguous' in r.get('reason', '') for r in result.source_refs)
